import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { mkdir, readFile, writeFile } from 'node:fs/promises';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const repoRoot = path.resolve(__dirname, '..');

const files = [
  path.join(repoRoot, 'lib/interaction/direct-manipulation.js'),
  path.join(repoRoot, 'lib/interaction/manipulation-controller.js'),
  path.join(repoRoot, 'lib/interaction/free-drag-controller.js'),
  path.join(repoRoot, 'lib/runtime/camera-presets.js'),
  path.join(repoRoot, 'lib/runtime/theme-presets.js'),
  path.join(repoRoot, 'lib/runtime/scene-shell.js'),
  path.join(repoRoot, 'lib/runtime/timeline.js'),
  path.join(repoRoot, 'lib/runtime/anchor-motion.js'),
  path.join(repoRoot, 'lib/effects/particle-pool.js'),
  path.join(repoRoot, 'lib/effects/bubble-field.js'),
  path.join(repoRoot, 'lib/effects/steam-field.js'),
  path.join(repoRoot, 'lib/effects/spark-field.js'),
  path.join(repoRoot, 'lib/effects/pour-stream.js'),
  path.join(repoRoot, 'lib/effects/glow-ring.js'),
  path.join(repoRoot, 'lib/effects/flame-plume.js'),
  path.join(repoRoot, 'lib/effects/color-transition.js'),
  path.join(repoRoot, 'lib/effects/material-progress.js'),
  path.join(repoRoot, 'lib/effects/smoke-field.js'),
  path.join(repoRoot, 'lib/effects/contained-gas-field.js'),
  path.join(repoRoot, 'lib/effects/reaction-zone.js'),
  path.join(repoRoot, 'lib/effects/precipitate-cloud.js'),
  path.join(repoRoot, 'lib/effects/gas-collection-bubbles.js'),
  path.join(repoRoot, 'lib/effects/heat-shimmer.js'),
  path.join(repoRoot, 'lib/reactions/reaction-flow.js'),
  path.join(repoRoot, 'lib/reactions/pour-into-vessel.js'),
  path.join(repoRoot, 'lib/reactions/acid-base-indicator.js'),
  path.join(repoRoot, 'lib/reactions/metal-displacement.js'),
  path.join(repoRoot, 'lib/reactions/dehydration-carbonization.js'),
  path.join(repoRoot, 'lib/reactions/acid-metal-gas.js'),
  path.join(repoRoot, 'lib/reactions/methane-combustion.js'),
  path.join(repoRoot, 'lib/reactions/water-electrolysis.js'),
  path.join(repoRoot, 'lib/testing/harness.js'),
];

const outputPath = path.join(repoRoot, 'templates/shared-inline-snippet.js');

function stripModuleSyntax(source) {
  return source
    .replace(/^import[\s\S]*?;\n?/gm, '')
    .replace(/^export\s*\{[^}]*\}\s*from\s*['"][^'"]+['"];?\n?/gm, '')
    .replace(/^export \{[\s\S]*?\};?$/gm, '')
    .replace(/^export /gm, '')
    .trim();
}

async function buildInlineSnippet() {
  const sections = await Promise.all(files.map((filePath) => readFile(filePath, 'utf8')));
  const body = sections.map(stripModuleSyntax).join('\n\n');
  const snippet = `// Generated by scripts/build-shared-inline-bundle.mjs
// Paste this inside a <script type="module"> block after importing THREE.

${body}

const ChemSharedLib = {
  THREE,
  cameraPresets,
  getCameraPreset,
  themePresets,
  getThemePreset,
  updatePointerFromEvent,
  setPointerCaptureSafe,
  releasePointerCaptureSafe,
  setControlsDragging,
  createManipulationController,
  createFreeDragController,
  createSceneShell,
  intersectPointerPlane,
  getWorldBounds,
  modelsOverlapOrNear,
  canAttemptOrderedStep,
  hasActiveCompletion,
  isStepBusy,
  lerpObjectPose,
  beginStepCompletion,
  clearStepCompletion,
  runStepCompletion,
  completeOrderedOverlapStep,
  clamp01,
  lerp,
  smoothstep01,
  segment,
  sequenceProgress,
  computeAnchorPlacementPose,
  applyAnchorPlacement,
  createGuidedAnchorMotion,
  createGuidedPourMotion,
  createSequencedPourController,
  createContextualLabelPolicy,
  createSpriteTexture,
  createSoftCircleTexture,
  createParticlePool,
  createBubbleField,
  createSteamField,
  createSparkField,
  createPourStream,
  createGlowRing,
  createFlamePlume,
  createColorTransition,
  createMaterialProgress,
  createSmokeField,
  createVesselReactionZone,
  particlePoolContainedInReactionZone,
  objectContainedInReactionZone,
  createContainedGasField,
  createPrecipitateCloud,
  createGasCollectionBubbles,
  createHeatShimmer,
  createReactionFlow,
  createPourIntoVesselReaction,
  createAcidBaseIndicatorReaction,
  createMetalDisplacementReaction,
  createDehydrationCarbonizationReaction,
  createAcidMetalGasReaction,
  createMethaneCombustionReaction,
  createWaterElectrolysisReaction,
  getCanvasBox,
  canvasPoint,
  projectWorldToCanvas,
  installFlameTestHarness,
  installCoursewareTestHarness,
};

globalThis.ChemSharedLib = ChemSharedLib;
`;

  await mkdir(path.dirname(outputPath), { recursive: true });
  await writeFile(outputPath, `${snippet}\n`, 'utf8');
  return outputPath;
}

const builtPath = await buildInlineSnippet();
console.log(`Built shared inline snippet: ${builtPath}`);
